"""User guide and illustrative examples; no live trading or data mutation."""
import pandas as pd
AUTO_HELP = '최근 자동 작업은 GitHub Actions의 Market scan v9이 마지막으로 저장한 분석 회차입니다. 예약 실행과 수동 Run workflow 모두 포함될 수 있습니다. 예: 275개 조회 시도, 254개 성공이면 성공률 92.4%, 실패 21개입니다. 투자 성공률이 아니며 새로고침만으로 새 작업을 시작하지 않습니다.'

def example(k):
    if k=='RSI(14)': return '예: RSI 86→75→65, 주가 12,000→10,000→10,200원이라면 과열 완화와 반등을 관찰합니다. 10,000원 아래로 밀리고 회복하지 못하면 지지 가설을 다시 검토합니다. RSI 하락만으로 매수하지 않습니다.'
    if k=='MACD 히스토그램': return '예: +0.8→+0.6→+0.4→+0.2는 양수이지만 상승 힘이 둔화되는 모습입니다. 반대로 +0.2→+0.4→+0.6은 강화입니다. 최근 일봉의 막대를 비교하고 0선 아래 전환 여부도 확인하세요.'
    if k=='거래량/20일 평균': return '예: 평균 100만 주, 오늘 79만 주면 0.79배입니다. 저항 10,000원을 10,300원으로 돌파하며 150만 주가 거래되면 1.5배로 돌파를 뒷받침할 수 있습니다. 하락하면서 150만 주라면 매도 압력일 수도 있습니다. 장 종료 후 비교하세요.'
    if k in ('5일선','20일선','60일선'): return '예: 평균선 10,000원, 주가 12,000→10,050→10,300원이라면 평균선 부근 반등을 관찰합니다. 9,700원으로 내려간 뒤 10,000원을 회복하지 못하면 지지 약화 가능성이 있습니다. 평균선 자체도 매일 바뀝니다.'
    if '매수 관찰가' in k or '지지 후보' in k: return '예: 지지 후보 10,000원에서 10,050→10,300원으로 반등하고 하락일 거래량보다 반등일 거래량이 늘면 지지 가능성을 검토합니다. 9,500원으로 이탈 후 회복하지 못하면 관찰 계획을 재검토하세요.'
    if '목표 관찰가' in k or '저항 후보' in k: return '예: 진입 10,000원, 목표 11,000원, 손실 제한 9,500원이면 가정 수익 10%, 위험 5%, 손익비 2:1입니다. 11,000원 부근에서 반복 하락하면 저항을 의심합니다. 체결과 수익은 보장되지 않습니다.'
    if 'ATR' in k or '손실' in k or '손절' in k: return '예: 진입 10,000원, ATR 500원, 손실 제한 9,500원이면 손실 거리는 ATR 1배입니다. 1회 허용 손실 100,000원이라면 비용 제외 최대 200주입니다. 급락 시 손실은 더 커질 수 있습니다.'
    if '점수' in k: return '예: 추세 30점 중 20점이라면 만점 대비 10점 부족합니다. 가격과 이동평균 배열을 확인하고 다른 세부 점수도 비교하세요. 80점은 상승 확률 80%가 아닙니다.'
    if k=='기준 종가' or k=='기준일': return '예: 11월 12일 오후 분석인데 가격 기준일이 11월 11일이면 전일 자료일 수 있습니다. 12일 장중 일봉이면 확정 종가가 아닐 수 있으므로 증권사 호가 및 장 종료 여부를 확인하세요.'
    return '예: 분석 완료가 오늘이어도 가격 기준일이 어제라면 오늘 확정 종가를 사용한 것이 아닙니다. 표시 단위와 기준일을 먼저 대조하세요.'

def show(st, score_guide, period_options):
    st.header('📖 프로그램 사용 설명서')
    st.caption('R15 · 예시는 모두 가상 수치입니다. 실제 투자 추천이나 확정 수익이 아닙니다.')
    with st.expander('01. 프로그램 전체 작동 원리', expanded=True):
        st.markdown('**종목 목록 → 순환 시세 조회 → 기술점수 계산 → GitHub 저장 → 최근 7일 후보 필터 → 기간별 추천점수 정렬 → TOP10 → 개별 상세분석 → 정기 기록과 사후 검증**')
        st.write('전체 등록 종목을 한 번에 분석하지 않습니다. Market scan v9은 신규 순환 후보 250개와 기존 상위 후보 25개를 대상으로 설정되어 있으며 중복·실패 등으로 실제 수는 달라집니다. 저장된 최신 결과를 종목별로 선택합니다. 추천 화면의 뉴스는 별도 참고 자료이며 추천점수에 직접 합산되지 않습니다.')
    with st.expander('02. 자동분석과 새로고침의 차이'):
        st.write(AUTO_HELP)
        st.table(pd.DataFrame([['예약 자동분석','평일 10시·15시 KST 예정','시세 조회, 점수 및 기록 저장; 지연·실패 가능'],['GitHub 수동 실행','Run workflow','순환 분석 및 기존 검증 갱신; 정기 회차는 생성하지 않음'],['브라우저 새로고침','사용자가 화면 갱신','저장 자료 다시 읽기; 새 스캔을 시작하지 않음'],['추천 검색','기간·시장·테마 선택','저장 후보 재정렬; 상위 종목 수익률 별도 조회'],['개별 상세분석','분석 버튼','해당 종목 일봉 조회 또는 캐시 사용']],columns=['동작','시점','변경 내용']))
        st.write('지수 캐시 15분, 뉴스 30분, 개별 기술분석 60분, TOP10 수익률 5분입니다. 캐시가 남아 있으면 버튼이나 새로고침 후에도 같은 값일 수 있습니다. 배포 서버에 새 GitHub 데이터가 반영되어야 저장 점수가 달라집니다. 새로고침 시 선택 상태가 초기화될 수 있습니다.')
    with st.expander('03. 분석 종목 수와 숫자의 의미'):
        st.table(pd.DataFrame([['등록 종목','15,896','검색 목록 전체'],['누적 분석','3,302','저장된 고유 종목; 오래된 자료 포함 가능'],['최근 7일','예: 2,000','최근 7일 분석 완료 후보; 전체 목록 아님'],['최근 실행 성공','254/275','조회 성공률 92.4%, 투자 적중률 아님'],['기존 배치/표본','865/48','이전 고급 도구의 별도 범위']],columns=['항목','가상/화면 예시','의미']))
        st.write('누적 범위 3,302÷15,896≈20.8%. 새 종목을 분석하면 증가할 수 있고 기존 종목 재분석만 하면 그대로일 수 있습니다. 최근 7일 수는 오래된 결과가 제외되면서 감소할 수도 있습니다.')
    with st.expander('04. 추천점수와 추천종목 선정 원리'):
        p=st.selectbox('계산식을 볼 투자 기간',period_options,key='qp_manual_period')
        st.text(score_guide(p))
        st.write('스윙 예: 기술점수 80, 5일 수익률 4%, 20일 수익률 8%, 연율 변동성 0.4(40%)이면 48+1.4+2−4=47.4점입니다. 변동성이 0.6으로 증가하면 45.4점으로 감소합니다. 같은 조건에서 점수가 높은 종목부터 TOP10을 선정합니다. 수익률은 극단값을 제한하며 누락 수익률은 0, 누락 변동성은 1, 누락 기술점수는 0으로 대체됩니다. 추천점수는 확률이 아니며 100점 초과 또는 음수도 가능합니다. 상세 기술점수는 별도 최신 일봉 분석이므로 저장 기술점수와 다를 수 있습니다. 테마는 종목명 키워드 필터이며 정밀 산업 분류가 아닙니다.')
    with st.expander('05. 기술지표와 실제 확인 방법'):
        for k in ['RSI(14)','MACD 히스토그램','거래량/20일 평균','20일선','지지 후보','저항 후보','ATR(14)','종합 점수(100)','기준 종가']:
            st.markdown('**'+k+'**');st.write(example(k))
            if k=='MACD 히스토그램': st.bar_chart(pd.DataFrame({'히스토그램':[.2,.4,.6,.8,.6,.4,.2]},index=range(1,8)))
            if k=='거래량/20일 평균': st.bar_chart(pd.DataFrame({'거래량(만 주)':[79,100,150,200]},index=range(1,5)))
            if k=='20일선': st.line_chart(pd.DataFrame({'주가':[12000,11000,10050,10300,10800],'20일선':[9900,9950,10000,10020,10050]}))
            if k=='지지 후보': st.line_chart(pd.DataFrame({'주가':[12000,11000,10050,10300,10020,11000],'지지 후보':[10000]*6}))
        st.write('실제 확인은 증권사 일봉 차트 또는 관리자 고급 도구의 가격 차트에서 진행하세요. 예시 차트는 실제 종목 데이터가 아닙니다.')
    with st.expander('06. 추천순위와 가격 그래프'):
        st.write('왼쪽 파란색 순위는 1위가 위, 오른쪽 빨간색은 저장 일봉 가격입니다. 11은 해당 조건 TOP10 밖, 빈칸은 기록 없음입니다. 가격이 상승해도 다른 종목 점수가 더 높으면 순위는 떨어질 수 있습니다. 가격 기준일과 예약 시각은 다릅니다. 국내 원화, 미국 달러이며 실시간 체결가는 아닙니다.')
    with st.expander('07. 추천종목 검증 및 수익률'):
        st.write('정기 회차별 TOP10을 고정 저장하고 추천 이후 첫 거래일의 완료된 수정종가를 기준으로 그 뒤 1·5·20거래일 가격을 비교합니다. 예: 기준가 10,000원, 5거래일 후 10,500원이면 +5%. 5일 검증이 아직 불가능하면 미확인입니다. 평균 수익률은 확인된 기록만 평균하며 같은 종목이 여러 회차 포함될 수 있습니다. 수수료·환율·실제 체결은 반영하지 않습니다. 기존 검증 기록은 별도 기준으로 표시합니다. 예약 지연, 데이터 부족 또는 검증 처리 한도 때문에 결과가 늦어질 수 있습니다.')
    with st.expander('08. 관리자 메뉴 사용 방법'):
        st.write('분석 현황: 전체 등록·누적·최근 7일·최근 실행 성공 및 시장별 범위 확인. 저장 종목 조회: 종목명/코드 검색, 저장 가격과 기준일 확인, CSV 다운로드. 검증 기록: 정기 회차 수와 기존 검증 기록 확인. 기존 고급 도구: 이전 대표 표본, 배치 자료, 종합 투자 리포트, 차트, 수량 계산. 서로 다른 범위의 숫자를 합산하지 마세요.')
    with st.expander('09. 투자금과 위험 관리'):
        st.write('예: 투자금 1,000만원, 거래당 1% 허용 손실 10만원, 하루 3% 한도 30만원. 진입 10,000원, 손실 제한 9,500원이면 비용 제외 200주 이하를 검토합니다. 실제 주문은 실행하지 않으며 급락·환율·수수료로 손실이 커질 수 있습니다. 뉴스·실적·공시·호가를 별도로 확인하세요.')
    with st.expander('10. 오류 발생 시 해결 방법'):
        st.write('추천 없음: 최근 7일 데이터 및 시장·테마 조건 확인. 순위/가격 그래프 공백: 예약 기록 생성 여부 확인. 검증 대기: 거래일 경과 및 후속 검증 실행 확인. 값이 그대로: 분석 기준일, 캐시, GitHub 최신 커밋과 Streamlit 반영 여부 확인. 시세 조회 실패: 관리자 실패 기록과 Actions 로그 확인. 수동 실행은 정기 기록을 대신 생성하지 않습니다.')
